"use strict";
const crypto = require("crypto");
const TARGET = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const TITLE = "Quarterly Report 2026";

// Reasonable slug candidates for this title.
const seps = ["-", "_", " ", "."];
const candidates = new Set();
for (const a of seps) for (const b of seps) {
  candidates.add("quarterly" + a + "report" + b + "2026");
  candidates.add("quarterly" + a + "report" + a + "2026");
}
candidates.add("quarterly-report-2026");
candidates.add("quarterly_report_2026");
candidates.add("quarterly-report-2026 ");
candidates.add(TITLE.toLowerCase());
candidates.add(TITLE.toLowerCase().replace(/[^a-z0-9]+/g, "_"));

console.log("Target digest:", TARGET);
for (const c of candidates) {
  const h = crypto.createHash("sha256").update(c, "utf8").digest("hex");
  const mark = h === TARGET ? "  <<< MATCHES TARGET" : "";
  console.log(
    (h === TARGET ? "[MATCH] " : "        ") +
      JSON.stringify(c) +
      "  contains _2026: " + c.includes("_2026") + mark
  );
}
console.log(
  "\nConclusion: target digest equals sha256('quarterly-report-2026')? " +
    (crypto.createHash("sha256").update("quarterly-report-2026", "utf8").digest("hex") === TARGET)
);

